// Compass points that differ in Dutch; the others are written the same
const CARDINALS = {
  en: {},
  nl: { NE: 'NO', E: 'O', SE: 'ZO', S: 'Z', SW: 'ZW' }
};

// The setting wins when it is en or nl (any case); 'device' or empty uses the device locale; anything else is en
function resolveLanguage(setting, locale) {
  const chosen = String(setting ?? '').trim();
  const source = chosen === '' || chosen.toLowerCase() === 'device' ? locale : chosen;
  const code = String(source ?? '')
    .trim()
    .slice(0, 2)
    .toLowerCase();
  return STRINGS[code] ? code : 'en';
}

function fill(template, values) {
  return String(template).replace(/\{(\w+)\}/g, (_, key) => (values && values[key] !== undefined ? values[key] : ''));
}

function conditionsText(window, lang) {
  const language = STRINGS[lang] ? lang : 'en';
  const text = STRINGS[language];
  const dry = window.qualifies && window.precipProbMax <= DRY_MAX_PROBABILITY;
  const cardinal = CARDINALS[language][window.windFromCardinal] || window.windFromCardinal;
  const temp = Math.round(window.apparentTempAvg) || 0; // `|| 0` turns -0 into 0
  return {
    sky: dry ? text.dry : `${text.rain} ${window.precipProbMax}%`,
    wind: `${window.windAvg} ${text.speed} ${cardinal}`,
    temp: `${temp}°C`
  };
}

function finiteOrZero(value) {
  return Number.isFinite(value) && value > 0 ? value : 0;
}

function formatKm(meters, lang) {
  const text = (Math.round(finiteOrZero(meters) / 100) / 10).toFixed(1);
  return lang === 'nl' ? text.replace('.', ',') : text;
}

function formatDuration(seconds) {
  const minutes = Math.round(finiteOrZero(seconds) / 60);
  return `${Math.floor(minutes / 60)}:${String(minutes % 60).padStart(2, '0')}`;
}

function formatPace(secondsPerKm) {
  const total = Math.round(finiteOrZero(secondsPerKm));
  return `${Math.floor(total / 60)}:${String(total % 60).padStart(2, '0')}`;
}

const FALLBACK_ZONE = 'UTC';
const RANGE_TEXT = /^(\d{1,2})-(\d{1,2})$/;
const DAY_MS = 86400000;

// Intl in TRMNL has English data only: always en-US, parts, never a locale string
function zonedParts(ms, timeZone) {
  const options = {
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
    second: '2-digit',
    hourCycle: 'h23'
  };
  let formatter;
  try {
    formatter = new Intl.DateTimeFormat('en-US', { ...options, timeZone: timeZone || FALLBACK_ZONE });
  } catch {
    formatter = new Intl.DateTimeFormat('en-US', { ...options, timeZone: FALLBACK_ZONE });
  }
  const parts = {};
  for (const part of formatter.formatToParts(new Date(ms))) parts[part.type] = part.value;
  return {
    year: Number(parts.year),
    month: Number(parts.month),
    day: Number(parts.day),
    hour: Number(parts.hour) % 24,
    minute: Number(parts.minute),
    second: Number(parts.second)
  };
}

const pad = value => String(value).padStart(2, '0');

function localDate(ms, timeZone) {
  const { year, month, day } = zonedParts(ms, timeZone);
  return `${year}-${pad(month)}-${pad(day)}`;
}

function localTime(ms, timeZone) {
  const { hour, minute } = zonedParts(ms, timeZone);
  return `${pad(hour)}:${pad(minute)}`;
}

function dateToUtcMs(date) {
  const [year, month, day] = date.split('-').map(Number);
  return Date.UTC(year, month - 1, day);
}

function addDays(date, days) {
  return new Date(dateToUtcMs(date) + days * DAY_MS).toISOString().slice(0, 10);
}

// Monday is 0
function dayOfWeek(date) {
  return (new Date(dateToUtcMs(date)).getUTCDay() + 6) % 7;
}

function weekDates(date) {
  const monday = addDays(date, -dayOfWeek(date));
  return Array.from({ length: 7 }, (_, index) => addDays(monday, index));
}

// The week number of the Thursday of this date's week, counted in that Thursday's year
function isoWeek(date) {
  const thursday = addDays(date, 3 - dayOfWeek(date));
  const firstOfYear = `${thursday.slice(0, 4)}-01-01`;
  const days = Math.round((dateToUtcMs(thursday) - dateToUtcMs(firstOfYear)) / DAY_MS);
  return Math.floor(days / 7) + 1;
}

// The instant at which the wall clock in the zone shows `date` and `hour` (24 is the next midnight). Two passes
// correct for a UTC offset that differs at the guess and at the result (DST change in between).
function zonedWall(date, hour, timeZone) {
  const wall = dateToUtcMs(date) + hour * 3600000;
  const offsetAt = ms => {
    const p = zonedParts(ms, timeZone);
    return Date.UTC(p.year, p.month - 1, p.day, p.hour, p.minute, p.second) - Math.floor(ms / 1000) * 1000;
  };
  const first = wall - offsetAt(wall);
  return wall - offsetAt(first);
}

function zonedMidnight(date, timeZone) {
  return zonedWall(date, 0, timeZone);
}

// End of the latest range that local day; 24 is the next midnight. Without a valid range: the end of the day.
function availabilityEnd(avail, date, timeZone) {
  let latest = 0;
  for (const piece of String(avail ?? '').split(',')) {
    const match = RANGE_TEXT.exec(piece.trim());
    if (!match) continue;
    const start = Number(match[1]);
    const end = Number(match[2]);
    if (end <= 24 && start < end && end > latest) latest = end;
  }
  return zonedWall(date, latest || 24, timeZone);
}

const DEFAULT_AVAILABILITY = '07-09,12-14,17-21';
const DEFAULT_DARK = 'avoid';
const DEFAULT_RAIN = '40';
const DEFAULT_SPORT = 'running';
const DEFAULT_LANGUAGE = 'device';
const WINDOW_URL = 'https://run.xadi.eu/api/window';
const NUMBER_TEXT = /^-?\d+(\.\d+)?$/;

function textOr(value, fallback) {
  return typeof value === 'string' && value !== '' ? value : fallback;
}

// A coordinate in the lat_lon text, rounded to 2 decimals like the polling URL does; null when not a number
function roundCoordinate(text, limit) {
  const trimmed = text.trim();
  if (!NUMBER_TEXT.test(trimmed)) return null;
  const value = Number(trimmed);
  if (Math.abs(value) > limit) return null;
  return Math.round(value * 100) / 100 || 0; // `|| 0` turns -0 into 0
}

function readLocation(value) {
  const parts = typeof value === 'string' ? value.split(',') : [];
  const lat = parts.length === 2 ? roundCoordinate(parts[0], 90) : null;
  const lon = parts.length === 2 ? roundCoordinate(parts[1], 180) : null;
  return lat === null || lon === null ? { lat: null, lon: null } : { lat, lon };
}

// Never throws: a missing trmnl, null custom_fields_values or non-string values give the defaults
function readSettings(input) {
  const trmnl = input && typeof input === 'object' ? input.trmnl : null;
  const plugin = trmnl && typeof trmnl === 'object' ? trmnl.plugin_settings : null;
  const fields = plugin && typeof plugin === 'object' ? plugin.custom_fields_values : null;
  const values = fields && typeof fields === 'object' ? fields : {};
  const { lat, lon } = readLocation(values.lat_lon);
  return {
    token: textOr(values.tredict_token, ''),
    lat,
    lon,
    availability: textOr(values.availability, DEFAULT_AVAILABILITY).replace(/ /g, ''),
    dark: textOr(values.dark, DEFAULT_DARK),
    rain: textOr(values.rain, DEFAULT_RAIN),
    sport: textOr(values.sport, DEFAULT_SPORT),
    language: textOr(values.language, DEFAULT_LANGUAGE),
    hasLocation: lat !== null && lon !== null
  };
}

// The same URL settings.yml renders for polling; Liquid's url_encode turns spaces into +
function windowUrl(settings) {
  if (!settings || !settings.hasLocation) return null;
  const avail = encodeURIComponent(settings.availability).replace(/%20/g, '+');
  const { lat, lon, dark, rain } = settings;
  return `${WINDOW_URL}?lat=${lat}&lon=${lon}&avail=${avail}&dark=${dark}&rain=${rain}`;
}

function buildBoard(input, { now }) {
  return { v: 1, fetchedAt: new Date(now).toISOString(), fetchedAtText: '' };
}

async function run(input) {
  return buildBoard(input, { fetch, now: Date.now() });
}
